parameters.text:
=Tu es le directeur marketing de la marque {{$json.brand}}.

Crée un kit commercial complet pour ce produit :
- Nom : {{$json.product_name}}
- Type : {{$json.product_type}}
- Cible : {{$json.target_customer}}
- Problème principal : {{$json.main_problem}}
- Bénéfice principal : {{$json.main_benefit}}
- Fonctionnalités : {{$json.features}}
- Fichiers inclus : {{$json.included_files}}
- Catégorie Etsy indicative : {{$json.etsy_category_hint}}
- Prix actuel : {{$json.price_eur}} €
- Langue : {{$json.language}}
- Ton : {{$json.tone}}

RÈGLES STRICTES
1. Réponds uniquement avec un objet JSON valide, sans Markdown.
2. N'invente aucune fonctionnalité ou garantie.
3. Pas de promesse médicale, juridique ou financière.
4. Titre Etsy <= 140 caractères.
5. Exactement 13 tags Etsy, chacun <= 20 caractères.
6. Prévois au moins 5 épingles Pinterest.
7. Prévois exactement 7 slides Instagram.
8. Prévois un script TikTok de 25 à 35 secondes.
9. Les hashtags n'ont pas d'espaces.
10. Le ton ne doit jamais culpabiliser les parents.
11. Chaque canal doit avoir un appel à l'action adapté.
12. Une validation humaine reste obligatoire.

SCHÉMA JSON OBLIGATOIRE
{
  "product": {
    "name": "string",
    "price_eur": 0,
    "audience": "string",
    "problem": "string",
    "positioning": "string",
    "unique_value_proposition": "string"
  },
  "etsy": {
    "title": "string",
    "description": "string",
    "tags": ["13 chaînes exactement"],
    "materials": ["chaînes"],
    "short_benefits": ["4 chaînes exactement"],
    "faq": [
      {"question": "string", "answer": "string"}
    ],
    "suggested_price_eur": 0,
    "launch_promo": "string",
    "image_alt_texts": ["7 chaînes exactement"]
  },
  "instagram": {
    "caption": "string",
    "carousel_slides": ["7 chaînes exactement"],
    "reel_hook": "string",
    "reel_caption": "string",
    "hashtags": ["10 à 15 chaînes"],
    "cta": "string"
  },
  "facebook": {
    "post": "string",
    "short_post": "string",
    "cta": "string"
  },
  "pinterest": {
    "pins": [
      {"title": "string", "description": "string", "visual_hook": "string", "cta": "string"}
    ]
  },
  "tiktok": {
    "hook": "string",
    "script_30s": "string",
    "shots": ["6 chaînes exactement"],
    "caption": "string",
    "hashtags": ["5 à 8 chaînes"],
    "cta": "string"
  },
  "email": {
    "subject": "string",
    "preheader": "string",
    "body": "string",
    "cta": "string"
  },
  "visuals": {
    "etsy_image_texts": ["7 chaînes exactement"],
    "instagram_visual_prompts": ["3 chaînes exactement"],
    "pinterest_visual_prompts": ["3 chaînes exactement"],
    "tiktok_broll_prompts": ["3 chaînes exactement"]
  },
  "seo": {
    "primary_keyword": "string",
    "secondary_keywords": ["5 à 10 chaînes"],
    "buyer_intent_terms": ["3 à 5 chaînes"]
  },
  "quality_control": {
    "claims_to_verify": ["chaînes"],
    "missing_information": ["chaînes"],
    "human_validation_required": true
  }
}

parameters.jsCode:
const raw = $json.output ?? $json.text ?? $json.response ?? '';

function stripCodeFence(value) {
  return String(value)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

let parsed;
try {
  parsed = JSON.parse(stripCodeFence(raw));
} catch (error) {
  throw new Error('Réponse IA non JSON : ' + error.message);
}

const errors = [];
const warnings = [];

const requireObject = (obj, key) => {
  if (!obj[key] || typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
    errors.push(`Section absente ou invalide : ${key}`);
  }
};

['product','etsy','instagram','facebook','pinterest','tiktok','email','visuals','seo','quality_control']
  .forEach(key => requireObject(parsed, key));

if (!parsed.etsy?.title || parsed.etsy.title.length > 140) {
  errors.push('Titre Etsy absent ou supérieur à 140 caractères.');
}

if (!Array.isArray(parsed.etsy?.tags) || parsed.etsy.tags.length !== 13) {
  errors.push('Il faut exactement 13 tags Etsy.');
} else {
  parsed.etsy.tags.forEach((tag, i) => {
    if (typeof tag !== 'string' || tag.length > 20) {
      errors.push(`Tag Etsy ${i + 1} invalide ou supérieur à 20 caractères.`);
    }
  });
}

if (!Array.isArray(parsed.instagram?.carousel_slides) || parsed.instagram.carousel_slides.length !== 7) {
  errors.push('Il faut exactement 7 slides Instagram.');
}

if (!Array.isArray(parsed.pinterest?.pins) || parsed.pinterest.pins.length < 5) {
  errors.push('Il faut au moins 5 épingles Pinterest.');
}

if (!Array.isArray(parsed.tiktok?.shots) || parsed.tiktok.shots.length !== 6) {
  errors.push('Il faut exactement 6 plans TikTok.');
}

if (parsed.quality_control?.human_validation_required !== true) {
  errors.push('La validation humaine doit rester obligatoire.');
}

const forbiddenClaims = /(garanti|sans conflit|résout tous|100% efficace|juridiquement conforme)/i;
const corpus = JSON.stringify(parsed);
if (forbiddenClaims.test(corpus)) {
  warnings.push('Une formulation potentiellement excessive a été détectée.');
}

return [{
  json: {
    status: errors.length === 0 ? 'READY_FOR_HUMAN_REVIEW' : 'NEEDS_CORRECTION',
    validation_errors: errors,
    validation_warnings: warnings,
    generated_at: new Date().toISOString(),
    marketing_package: parsed
  }
}];
